content.content:
=== marketplace.json ===
{
  "$schema": "https://anthropic.com/claude-code/marketplace.schema.json",
  "name": "agent-workflows",
  "description": "This repository is its own marketplace: it hosts the agent-workflows plugin from the same tree it develops it in, so the placed copy and the tested copy are one thing.",
  "owner": {
    "name": "dogkeeper886"
  },
  "plugins": [
    {
      "name": "agent-workflows",
      "description": "The layer wrapped around mattpocock/skills, which carries an idea only as far as a commit. Adds the ship tail (ship-create-pr, ship-merge) that takes it to merged, a finish review that runs the project's tooling and clears the leftovers a diff review cannot see, a report contract, and review gates for existing documents. Also ships doc-workflow (doc-*) for READMEs. Run setup-agent-workflows once per project: it writes the .claude/rules/project-profile.md every unit resolves its values from.",
      "source": "./plugins/agent-workflows",
      "category": "workflow",
      "homepage": "https://github.com/dogkeeper886/agent-workflows"
    }
  ]
}

=== plugin.json ===
{
  "$schema": "https://anthropic.com/claude-code/plugin.schema.json",
  "name": "agent-workflows",
  "description": "The layer around mattpocock/skills: the ship tail (ship-create-pr, ship-merge), the finish review, the report contract, plus doc-workflow (doc-*). Start with setup-agent-workflows, which writes this project's values. Doctrine travels in this plugin; a project's values stay in that project's .claude/rules/project-profile.md.",
  "author": {
    "name": "dogkeeper886"
  },
  "homepage": "https://github.com/dogkeeper886/agent-workflows",
  "license": "MIT"
}

